import { Directive, EventEmitter, HostListener, Input, Output } from "@angular/core";

@Directive({
	selector: '[espdSwipe]',
	standalone: true
})
export class SwipeDirective {

	@Input() orientation: 'horizontal' | 'vertical' = 'horizontal';

	@Output() next = new EventEmitter<void>();
	@Output() previous = new EventEmitter<void>();

	startCoord = [0, 0];
	startTime = 0;

	@HostListener('touchstart', ['$event'])
	onTouchStart($event: TouchEvent): void {
		this.startCoord = [$event.changedTouches[0].clientX, $event.changedTouches[0].clientY];
		this.startTime = new Date().getTime();
	}

	@HostListener('touchend', ['$event'])
	onTouchEnd($event: TouchEvent): void {
		const coord: [number, number] = [$event.changedTouches[0].clientX, $event.changedTouches[0].clientY];
		const vector: [number, number] = [coord[0] - this.startCoord[0], coord[1] - this.startCoord[1]];
		const duration = new Date().getTime() - this.startTime;
		const hypotenuse = Math.sqrt(vector[0] * vector[0] + vector[1] * vector[1]);

		if (duration < 1000 // Quick enough
			&& Math.abs(hypotenuse) >= 30 // Far enough
			&& this.isCorrectOrientation(vector)) {
			if (vector[this.orientation === 'horizontal' ? 0 : 1] < 0) {
				this.next.emit();
			} else {
				this.previous.emit();
			}
		}
	}

	private isCorrectOrientation(vector: [number, number]): boolean {
		const primaryComponent = this.orientation === 'horizontal' ? 0 : 1;
		const secondaryComponent = 1 - primaryComponent;
		return Math.abs(vector[primaryComponent]) > Math.abs(vector[secondaryComponent] * 3); // primary component is greater than 3x secondary component
	}
}